```ts
import { DurableObject } from "cloudflare:workers";

const HOUR_MS = 60 * 60 * 1000;

export interface Env {
  CHAT_ROOM: DurableObjectNamespace<ChatRoomState>;
}

export class ChatRoomState extends DurableObject<Env> {
  // Tail of the write queue. Each write chains onto this so writes run one at a time.
  private writeChain: Promise<unknown> = Promise.resolve();

  constructor(ctx: DurableObjectState, env: Env) {
    super(ctx, env);
    ctx.blockConcurrencyWhile(async () => {
      ctx.storage.sql.exec(`
        CREATE TABLE IF NOT EXISTS kv (
          key TEXT PRIMARY KEY,
          value TEXT NOT NULL
        )
      `);
      // Alarms survive eviction, so only schedule one if none is pending.
      if ((await ctx.storage.getAlarm()) === null) {
        await ctx.storage.setAlarm(Date.now() + HOUR_MS);
      }
    });
  }

  // Runs fn after every previously queued write has settled.
  private serialize<T>(fn: () => T | Promise<T>): Promise<T> {
    const run = this.writeChain.then(fn);
    this.writeChain = run.catch(() => {});
    return run;
  }

  async put(key: string, value: unknown): Promise<void> {
    await this.serialize(() => {
      this.ctx.storage.sql.exec(
        `INSERT INTO kv (key, value) VALUES (?, ?)
         ON CONFLICT(key) DO UPDATE SET value = excluded.value`,
        key,
        JSON.stringify(value)
      );
    });
  }

  async get<T = unknown>(key: string): Promise<T | undefined> {
    const row = this.ctx.storage.sql
      .exec<{ value: string }>("SELECT value FROM kv WHERE key = ?", key)
      .toArray()[0];
    return row === undefined ? undefined : (JSON.parse(row.value) as T);
  }

  async alarm(): Promise<void> {
    try {
      await this.serialize(() => {
        this.ctx.storage.sql.exec(
          `INSERT INTO kv (key, value) VALUES ('last_tick', ?)
           ON CONFLICT(key) DO UPDATE SET value = excluded.value`,
          JSON.stringify(Date.now())
        );
      });
    } finally {
      // Reschedule even if the write failed. The runtime also retries a throwing alarm.
      await this.ctx.storage.setAlarm(Date.now() + HOUR_MS);
    }
  }
}
```

The class is in `ChatRoomState`. Writes go through a promise chain, `put` and `alarm` both use it, and the constructor schedules the first hourly alarm only if none is pending. Nothing was run, since this is a code-only answer and the Cloudflare tools here are dry runs.
